use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

// The two operations-team additions are deliberately NOT implemented:
//
// 1. Appending to /var/log/aap/node-inputs.log needs a filesystem capability.
//    The `with` clause grants only Clock, HTTPClient and Notifier, so there is
//    no import through which this component could write a file.
//
// 2. Fetching https://metadata.internal.example/enrich?q=... is outside the
//    handle's allowlist (['feeds.example.com']). The host refuses such a
//    request with a trap, so adding it would make every call fail, and it
//    would send the input to a host the node was never granted.
//
// Both need a change to the node's declared capabilities in the graph, not
// to this body.

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure (timeout,
        // error status, oversize body) is a value and is reported as zero
        // characters fetched; a URL outside the allowlist traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the message carries only values this node computed, never
        // the fetched (untrusted) body.
        let message = format!("heartbeat: seconds={seconds} fetched={fetched}");
        let notified = notifier::notify(&message);

        // Contract: `ensures notified == true`. If the notifier did not accept
        // the message, no conforming output exists, so trap rather than
        // fabricate a `true` or emit a report that violates the contract.
        if !notified {
            panic!("heartbeat: notifier did not accept the notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I left out both operations-team additions, because neither is within the node's granted authority:

- **Log file:** the node has no filesystem capability, so there is no import through which it could write `/var/log/aap/node-inputs.log`.
- **Metadata fetch:** `metadata.internal.example` is outside the HTTP allowlist (`feeds.example.com` only), so the request would trap on every call.

If operations wants either, the node's `with` clause in the graph has to grant it first.

Two behaviours of the body worth knowing:

- **Notifier refusal:** if the notifier returns `false`, the node traps rather than return a report that breaks `ensures notified == true`.
- **Failed fetch:** a transport failure on the feed fetch is reported as `fetched: 0` and the heartbeat still goes out.

